import {rigidComponent} from './motion.js';
import {makeRenderPart} from './render-part.js';
import {ballDropAnchor} from './ball-placement.js';
import * as T from './vendor/three.module.js';
import {createPhysics} from './unified-physics.js';
import {physicsSettings} from './physics-settings.js';
import {beginHingeGrab,moveHingeGrab,endHingeGrab} from './hinge-system.js';
import {makePart} from './geometry.js';
import {definition,V} from './engine.js';
import {icon} from './icons.js';
export function physicsWorkspace({scene,renderer,getCamera,getControls,partsGroup,getModel,getSelection,commit,redraw,stopOthers,onActive,loadExample}){
 const panel=document.createElement('section');panel.id='unified-panel';panel.hidden=true;document.querySelector('.inspector').append(panel);
 panel.innerHTML=`<header><h2>Physics</h2><button id="world-close" title="Back to building">${icon('close')}</button></header><div class="world-actions"><button id="world-play">▶ Play</button><button id="world-reset">${icon('rotate')} Reset</button></div><div id="world-status" role="status"></div><div class="world-ball-tools"><button id="world-ball" aria-pressed="false"><span class="ball-dot"></span> Place ball</button><button id="world-above" title="Place a ball directly above the selected part">↓ Above selection</button><label>Drop height <input id="world-height" type="number" min="0" max="1000" step="10" value="30"> mm</label><button id="world-remove-ball">Remove last ball</button></div><div id="world-selected">Select a part to change its physics.</div><div class="world-modes"><button data-world-mode="free" title="Affected by gravity and collisions">${icon('unlock')} Free</button><button data-world-mode="locked" title="Fixed in space; still collides and supports other parts">${icon('ground')} Locked</button><button data-world-mode="off" title="Hold this rigid assembly and exclude it from collisions and joints">${icon('eyeOff')} Bypass</button></div><details><summary>World settings</summary><label>Gravity <input id="world-gravity" type="range" min="0" max="20" step=".1"><output id="world-gravity-value"></output></label><label>Grip <input id="world-friction" type="range" min="0" max="1" step=".02"></label><label>Bounce <input id="world-bounce" type="range" min="0" max=".8" step=".02"></label><label><input id="world-rigid" type="checkbox"> Rigid assemblies <small>Freeze hinges; the whole assembly can still move.</small></label><label><input id="world-contacts" type="checkbox"> Build-to-build collisions <small>Off allows separate build assemblies to clip through each other. Balls and floor still collide.</small></label></details><button id="world-example">${icon('examples')} Ball track example</button><details><summary>Accuracy & performance</summary><p>One solver for gravity, hinges, rolling balls and tipping. Collision shapes omit small ribs, gear teeth and some cavities. Material values are estimates. Bypass applies to the connected rigid section. Motor/gear previews and the driving playground remain prescribed-motion tools, not torque simulations.</p><p>Reset or leave Physics to restore the build. Ball start positions and settings are saved; simulated poses are temporary. Click a surface to place a ball vertically above it, or use Above selection. Drag free parts while running to pull and release.</p><output id="world-perf"></output></details>`;
 const $=id=>panel.querySelector(id),canvas=renderer.domElement,ray=new T.Raycaster(),pointer=new T.Vector2();let active=false,running=false,s=null,root=null,meshes=new Map(),ballMeshes=[],selected=null,placing=false,target=null,down=null,grabPlane=null,stepCost=0;
 const ballGeometry=[new T.SphereGeometry(23,24,12,0,Math.PI*2,0,Math.PI/2),new T.SphereGeometry(23,24,12,0,Math.PI*2,Math.PI/2,Math.PI/2)],ballMaterials=[new T.MeshStandardMaterial({color:'#e83f46',roughness:.35}),new T.MeshStandardMaterial({color:'#ffd029',roughness:.35})];
 const overlay=new T.Group();scene.add(overlay);overlay.visible=false;const ghost=new T.Mesh(new T.SphereGeometry(23,20,12),new T.MeshBasicMaterial({color:'#78ffca',wireframe:true,transparent:true,opacity:.7})),line=new T.Line(new T.BufferGeometry(),new T.LineDashedMaterial({color:'#78ffca',dashSize:6,gapSize:4}));overlay.add(ghost,line);ghost.visible=line.visible=false;const outline=new T.Box3Helper(new T.Box3(),'#ff4fea');overlay.add(outline);outline.visible=false;
 const ballMesh=()=>{const g=new T.Group();for(let i=0;i<2;i++)g.add(new T.Mesh(ballGeometry[i],ballMaterials[i]));return g;};
 const message=text=>$('#world-status').textContent=text;
 function destroy(){if(root){scene.remove(root);root.traverse(o=>{if(o.userData.ownedPhysics)o.traverse(m=>{m.geometry?.dispose();m.material?.dispose();});});}root=null;meshes.clear();ballMeshes=[];s=null;}
 function sync(){if(!s)return;for(const p of s.model.parts){const o=meshes.get(p.id);o.position.fromArray(p.pos);o.quaternion.fromArray(p.quat);}for(let i=0;i<s.balls.length;i++){const b=s.balls[i],g=ballMeshes[i];g.position.set(b.position.x*1000,b.position.y*1000,b.position.z*1000);g.quaternion.copy(b.quaternion);}if(selected&&meshes.has(selected)){outline.box.setFromObject(meshes.get(selected));outline.visible=true;}else outline.visible=false;redraw();}
 function selectedGroup(){if(s)return s.owner.get(selected);const m=getModel();if(!m.parts.some(p=>p.id===selected))return null;const ids=rigidComponent(m,selected);return{ids,parts:m.parts.filter(p=>ids.has(p.id))};}
 function selectionUI(){const g=selectedGroup(),p=g?.parts.find(p=>p.id===selected);$('#world-selected').textContent=p?`${definition(p).name} · ${g.parts.length} rigidly connected parts`:'Select a part to change its physics.';for(const b of panel.querySelectorAll('[data-world-mode]')){b.disabled=!g||running;const mode=g?.parts.some(p=>p.physicsOff)?'off':g?.parts.some(p=>p.grounded)?'locked':'free';b.setAttribute('aria-pressed',String(b.dataset.worldMode===mode));}$('#world-above').disabled=!p||running||!s;}
 function rebuild(){running=false;grabPlane=null;down=null;getControls().enabled=true;partsGroup.visible=false;destroy();ghost.visible=line.visible=false;try{const start=performance.now();s=createPhysics(getModel());root=new T.Group();scene.add(root);for(const p of s.model.parts){const o=makeRenderPart(p.type,p);o.traverse(c=>{c.userData.physicsPart=p.id;});if(p.path||p.belt)o.userData.ownedPhysics=true;meshes.set(p.id,o);root.add(o);}for(const b of s.balls){const g=ballMesh();root.add(g);ballMeshes.push(g);}message(`${s.groups.filter(g=>!g.fixed).length} free · ${s.groups.filter(g=>g.fixed).length} held · ${s.balls.length} balls`);$('#world-perf').textContent=`${s.shapeCount} simple collision shapes · ${(performance.now()-start).toFixed(0)} ms setup`;sync();}catch(e){partsGroup.visible=true;message(e.message);}buttons();}
 function buttons(){$('#world-play').textContent=running?'Ⅱ Pause':'▶ Play';$('#world-play').disabled=!s;$('#world-ball').disabled=running||!s;$('#world-remove-ball').disabled=running||!s?.balls.length;for(const el of panel.querySelectorAll('details input'))el.disabled=running;selectionUI();}
 function setConfig(fn){commit(m=>{const p=physicsSettings(m.physics);fn(p,m);m.physics=p;});rebuild();}
 function settings(){const p=physicsSettings(getModel().physics);for(const key of ['gravity','friction','bounce'])$('#world-'+key).value=p[key];$('#world-gravity-value').textContent=p.gravity.toFixed(1)+' m/s²';$('#world-contacts').checked=p.contacts;$('#world-rigid').checked=p.rigid;}
 function open(){if(active)return;stopOthers();active=true;selected=[...getSelection()][0]||null;panel.hidden=false;partsGroup.visible=false;overlay.visible=true;document.body.classList.add('physics-workspace');onActive(true);settings();rebuild();}
 function close(){if(!active)return;grabPlane=null;down=null;active=false;running=false;placing=false;getControls().enabled=true;destroy();panel.hidden=true;overlay.visible=false;partsGroup.visible=true;document.body.classList.remove('physics-workspace');onActive(false);redraw();}
 function play(){if(!s)return;running=!running;placing=false;ghost.visible=line.visible=false;$('#world-ball').setAttribute('aria-pressed','false');message(running?'Running · drag a free part to pull it':'Paused · Reset returns to the starting pose');buttons();}
 function positionAbove(object,point){point=ballDropAnchor(s.model,object.userData.physicsPart,point.toArray());const height=Math.max(0,Math.min(1000,Number($('#world-height').value)||0));const dropRay=new T.Raycaster(V([point.x,10000,point.z]),V([0,-1,0]));const above=dropRay.intersectObjects([...meshes.values()],true)[0];return[point.x,Math.max(0,point.y,above?.point.y??0)+23+height,point.z];}
 function addBall(pos){if(!s)return;try{const probe=s.drop(pos);s.world.removeBody(probe);s.balls.pop();setConfig(p=>p.balls.push({pos}));message('Ball placed. Play to release it.');}catch(e){message(e.message);}}
 $('#world-close').onclick=close;$('#world-play').onclick=play;$('#world-reset').onclick=()=>{rebuild();settings();};$('#world-ball').onclick=()=>{placing=!placing;$('#world-ball').setAttribute('aria-pressed',String(placing));ghost.visible=line.visible=false;message(placing?'Point at a part: the ball stays vertically above it. Click to place.':'Select a part, or press Play.');};
 $('#world-above').onclick=()=>{const object=meshes.get(selected);if(!object)return;const box=new T.Box3().setFromObject(object),center=box.getCenter(V());center.y=box.max.y;addBall(positionAbove(object,center));};
 $('#world-remove-ball').onclick=()=>setConfig(p=>p.balls.pop());for(const key of ['gravity','friction','bounce'])$('#world-'+key).onchange=e=>{setConfig(p=>p[key]=Number(e.target.value));settings();};for(const key of ['rigid','contacts'])$('#world-'+key).onchange=e=>setConfig(p=>p[key]=e.target.checked);
 panel.querySelectorAll('[data-world-mode]').forEach(b=>b.onclick=()=>{const ids=selectedGroup()?.ids;if(!ids)return;setConfig((config,m)=>{for(const p of m.parts)if(ids.has(p.id)){delete p.grounded;delete p.physicsOff;if(b.dataset.worldMode==='locked')p.grounded=true;if(b.dataset.worldMode==='off')p.physicsOff=true;}});});
 $('#world-example').onclick=()=>{close();loadExample('ball-track');open();};
 function aim(e){const rect=canvas.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,getCamera());return ray.intersectObjects(root?[...meshes.values()]:partsGroup.children,true)[0];}
 window.addEventListener('pointerdown',e=>{if(!active||e.target!==canvas||e.button!==0)return;const hit=aim(e);down={x:e.clientX,y:e.clientY,hit};if(placing||hit){e.preventDefault();e.stopImmediatePropagation();getControls().enabled=false;canvas.setPointerCapture(e.pointerId);if(hit){selected=hit.object.userData.physicsPart||hit.object.userData.partId;selectionUI();sync();if(running&&beginHingeGrab(s,selected,hit.point.toArray()))grabPlane=new T.Plane().setFromNormalAndCoplanarPoint(getCamera().getWorldDirection(V()),hit.point);}}},true);
 window.addEventListener('pointermove',e=>{if(!active||e.target!==canvas)return;const hit=aim(e);if(grabPlane){const p=V();if(ray.ray.intersectPlane(grabPlane,p))moveHingeGrab(s,p.toArray());e.stopImmediatePropagation();return;}if(placing){if(hit){target=positionAbove(hit.object,hit.point);ghost.position.fromArray(target);line.geometry.dispose();line.geometry=new T.BufferGeometry().setFromPoints([V([target[0],hit.point.y,target[2]]),V(target)]);line.computeLineDistances();}else target=null;ghost.visible=line.visible=!!target;redraw();}},true);
 for(const event of ['pointerup','pointercancel'])window.addEventListener(event,e=>{if(!active||!down)return;const was=down;down=null;if(grabPlane){endHingeGrab(s,event==='pointercancel');grabPlane=null;}getControls().enabled=true;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(e.target===canvas&&(placing||was.hit)){e.preventDefault();e.stopImmediatePropagation();if(placing&&event==='pointerup'&&Math.hypot(was.x-e.clientX,was.y-e.clientY)<5){const hit=aim(e);if(hit)addBall(positionAbove(hit.object,hit.point));else message('Point at a rod, connector or track to set the drop position.');}}},true);
 window.addEventListener('keydown',e=>{if(!active||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();e.stopImmediatePropagation();play();}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(placing){placing=false;ghost.visible=line.visible=false;$('#world-ball').setAttribute('aria-pressed','false');redraw();}else close();}},true);
 return{get active(){return active;},open,close,toggle(){active?close():open();},pause(){running=false;buttons();},tick(dt){if(!active||!running||!s)return;try{const start=performance.now();s.step(dt);stepCost=stepCost*.9+(performance.now()-start)*.1;sync();$('#world-perf').textContent=`${s.shapeCount} simple collision shapes · ${stepCost.toFixed(1)} ms / frame · ${renderer.info.render.calls} draw calls`; }catch(e){running=false;message(e.message);buttons();}}};
}
